css:
.circle{width:min(30vw,320px);aspect-ratio:1;border-radius:50%;background:#fff;
        border:1px solid #C9B98A;box-shadow:none;
        display:grid;place-content:center;text-align:center;padding:8%}
/* 情報量が多いとき：大円＋左端を画面外へ、中は左揃え */
.info{width:46vw;aspect-ratio:1;border-radius:50%;margin-left:-7vw;color:#fff;
      background:radial-gradient(120% 120% at 30% 20%,#26405f,#152a44);
      display:flex;align-items:center;padding-left:16%}
/* イラストを円の縁で断つ */
.node{position:relative;width:190px;aspect-ratio:1;border-radius:50%;overflow:hidden}
.node img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;object-position:top}
